package com.example.lending.domain;

import java.time.LocalDate;
import java.time.temporal.ChronoUnit;
import java.util.Objects;
import java.util.UUID;

public class Loan {

    static final int LOAN_PERIOD_DAYS = 14;
    static final int LATE_FEE_PER_DAY = 100;

    private final UUID id;
    private final UUID bookId;
    private final UUID memberId;
    private final LocalDate loanedAt;
    private final LocalDate dueAt;
    private LocalDate returnedAt;
    private final CreditCheck creditCheck;

    private Loan(UUID id, UUID bookId, UUID memberId, LocalDate loanedAt, LocalDate dueAt, LocalDate returnedAt,
                 CreditCheck creditCheck) {
        this.id = Objects.requireNonNull(id, "id");
        this.bookId = Objects.requireNonNull(bookId, "bookId");
        this.memberId = Objects.requireNonNull(memberId, "memberId");
        this.loanedAt = Objects.requireNonNull(loanedAt, "loanedAt");
        this.dueAt = Objects.requireNonNull(dueAt, "dueAt");
        if (dueAt.isBefore(loanedAt)) {
            throw new IllegalArgumentException("dueAt must not be before loanedAt");
        }
        this.returnedAt = returnedAt;
        this.creditCheck = Objects.requireNonNull(creditCheck, "creditCheck");
    }

    // 대출 생성은 Book.loanTo를 통해서만 (대출 가능 여부 규칙을 우회하지 않도록 package-private)
    static Loan start(UUID bookId, UUID memberId, LocalDate loanedAt, CreditCheck creditCheck) {
        return new Loan(UUID.randomUUID(), bookId, memberId, loanedAt, loanedAt.plusDays(LOAN_PERIOD_DAYS), null,
                creditCheck);
    }

    public static Loan reconstitute(UUID id, UUID bookId, UUID memberId, LocalDate loanedAt, LocalDate dueAt,
                                    LocalDate returnedAt, CreditCheck creditCheck) {
        return new Loan(id, bookId, memberId, loanedAt, dueAt, returnedAt, creditCheck);
    }

    public void markReturned(LocalDate returnedAt) {
        if (isReturned()) {
            throw new LoanAlreadyReturnedException(id);
        }
        if (returnedAt.isBefore(loanedAt)) {
            throw new IllegalArgumentException("returnedAt must not be before loanedAt");
        }
        this.returnedAt = returnedAt;
    }

    public boolean isReturned() {
        return returnedAt != null;
    }

    public boolean isOverdue(LocalDate today) {
        return today.isAfter(dueAt);
    }

    // 기한 당일까지는 연체가 아니고, 기한이 지난 날짜마다 1일씩 센다
    public int overdueDays() {
        if (!isReturned()) {
            throw new IllegalStateException("overdueDays requires a returned loan");
        }
        return (int) Math.max(0, ChronoUnit.DAYS.between(dueAt, returnedAt));
    }

    public int lateFee() {
        return overdueDays() * LATE_FEE_PER_DAY;
    }

    public UUID getId() {
        return id;
    }

    public UUID getBookId() {
        return bookId;
    }

    public UUID getMemberId() {
        return memberId;
    }

    public LocalDate getLoanedAt() {
        return loanedAt;
    }

    public LocalDate getDueAt() {
        return dueAt;
    }

    public LocalDate getReturnedAt() {
        return returnedAt;
    }

    public CreditCheck getCreditCheck() {
        return creditCheck;
    }
}
package com.example.lending.adapter.out.persistence;

import jakarta.persistence.CollectionTable;
import jakarta.persistence.Column;
import jakarta.persistence.ElementCollection;
import jakarta.persistence.Entity;
import jakarta.persistence.FetchType;
import jakarta.persistence.Id;
import jakarta.persistence.JoinColumn;
import jakarta.persistence.Table;

import java.time.Instant;
import java.time.LocalDate;
import java.util.ArrayList;
import java.util.List;
import java.util.UUID;

@Entity
@Table(name = "loan")
public class LoanJpaEntity {

    @Id
    private UUID id;

    @Column(nullable = false)
    private UUID bookId;

    @Column(nullable = false)
    private UUID memberId;

    @Column(nullable = false)
    private LocalDate loanedAt;

    @Column(nullable = false)
    private LocalDate dueAt;

    private LocalDate returnedAt;

    @Column(nullable = false)
    private boolean creditApproved;

    @Column(nullable = false)
    private int creditScore;

    @Column(nullable = false)
    private Instant creditCheckedAt;

    private String creditProviderName;

    private String creditProviderVersion;

    @ElementCollection(fetch = FetchType.EAGER)
    @CollectionTable(name = "loan_credit_reason_code", joinColumns = @JoinColumn(name = "loan_id"))
    @Column(name = "reason_code")
    private List<String> creditReasonCodes = new ArrayList<>();

    protected LoanJpaEntity() {
    }

    public LoanJpaEntity(UUID id, UUID bookId, UUID memberId, LocalDate loanedAt, LocalDate dueAt,
                         LocalDate returnedAt, boolean creditApproved, int creditScore, Instant creditCheckedAt,
                         String creditProviderName, String creditProviderVersion, List<String> creditReasonCodes) {
        this.id = id;
        this.bookId = bookId;
        this.memberId = memberId;
        this.loanedAt = loanedAt;
        this.dueAt = dueAt;
        this.returnedAt = returnedAt;
        this.creditApproved = creditApproved;
        this.creditScore = creditScore;
        this.creditCheckedAt = creditCheckedAt;
        this.creditProviderName = creditProviderName;
        this.creditProviderVersion = creditProviderVersion;
        this.creditReasonCodes = new ArrayList<>(creditReasonCodes);
    }

    public UUID getId() {
        return id;
    }

    public UUID getBookId() {
        return bookId;
    }

    public UUID getMemberId() {
        return memberId;
    }

    public LocalDate getLoanedAt() {
        return loanedAt;
    }

    public LocalDate getDueAt() {
        return dueAt;
    }

    public LocalDate getReturnedAt() {
        return returnedAt;
    }

    public boolean isCreditApproved() {
        return creditApproved;
    }

    public int getCreditScore() {
        return creditScore;
    }

    public Instant getCreditCheckedAt() {
        return creditCheckedAt;
    }

    public String getCreditProviderName() {
        return creditProviderName;
    }

    public String getCreditProviderVersion() {
        return creditProviderVersion;
    }

    public List<String> getCreditReasonCodes() {
        return creditReasonCodes;
    }
}
package com.example.lending.adapter.out.persistence;

import com.example.lending.domain.CreditCheck;
import com.example.lending.domain.Loan;

class LoanMapper {

    Loan toDomain(LoanJpaEntity entity) {
        CreditCheck creditCheck = new CreditCheck(entity.isCreditApproved(), entity.getCreditScore(),
                entity.getCreditReasonCodes(), entity.getCreditCheckedAt(),
                entity.getCreditProviderName(), entity.getCreditProviderVersion());
        return Loan.reconstitute(entity.getId(), entity.getBookId(), entity.getMemberId(),
                entity.getLoanedAt(), entity.getDueAt(), entity.getReturnedAt(), creditCheck);
    }

    LoanJpaEntity toEntity(Loan loan) {
        CreditCheck creditCheck = loan.getCreditCheck();
        return new LoanJpaEntity(loan.getId(), loan.getBookId(), loan.getMemberId(), loan.getLoanedAt(),
                loan.getDueAt(), loan.getReturnedAt(), creditCheck.approved(), creditCheck.score(),
                creditCheck.checkedAt(), creditCheck.providerName(), creditCheck.providerVersion(),
                creditCheck.reasonCodes());
    }
}
