package com.example.lending;

import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.ObjectMapper;
import org.junit.jupiter.api.Test;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.autoconfigure.web.servlet.AutoConfigureMockMvc;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.http.MediaType;
import org.springframework.test.web.servlet.MockMvc;

import java.util.Map;
import java.util.UUID;

import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.get;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.post;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.jsonPath;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.status;

@SpringBootTest
@AutoConfigureMockMvc
class MemberLoanListIntegrationTest {

    @Autowired
    MockMvc mockMvc;

    @Autowired
    ObjectMapper objectMapper;

    @Test
    void lists_only_active_loans_with_title_dates_and_total_count() throws Exception {
        String memberId = registerMember("노은서");
        String firstLoanId = loanBookOn(registerBook("목록 테스트 A"), memberId, "2026-02-02");
        loanBookOn(registerBook("목록 테스트 B"), memberId, "2026-02-03");
        loanBookOn(registerBook("목록 테스트 C"), memberId, "2026-02-04");

        mockMvc.perform(post("/loans/{loanId}/return", firstLoanId)
                        .contentType(MediaType.APPLICATION_JSON)
                        .content("{\"returnedAt\":\"2026-02-10\"}"))
                .andExpect(status().isOk());

        mockMvc.perform(get("/members/{memberId}/loans", memberId))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.page").value(0))
                .andExpect(jsonPath("$.size").value(20))
                .andExpect(jsonPath("$.totalCount").value(2))
                .andExpect(jsonPath("$.items.length()").value(2))
                .andExpect(jsonPath("$.items[0].title").value("목록 테스트 B"))
                .andExpect(jsonPath("$.items[0].loanedAt").value("2026-02-03"))
                .andExpect(jsonPath("$.items[0].dueAt").value("2026-02-17"))
                .andExpect(jsonPath("$.items[0].loanId").isNotEmpty())
                .andExpect(jsonPath("$.items[0].bookId").isNotEmpty())
                .andExpect(jsonPath("$.items[1].title").value("목록 테스트 C"));
    }

    @Test
    void pages_are_cut_by_size_while_total_count_covers_all_active_loans() throws Exception {
        String memberId = registerMember("문하람");
        for (int i = 0; i < 5; i++) {
            loanBookOn(registerBook("페이지 테스트 " + i), memberId, "2026-03-0" + (i + 1));
        }

        mockMvc.perform(get("/members/{memberId}/loans", memberId)
                        .param("page", "0").param("size", "2"))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.items.length()").value(2))
                .andExpect(jsonPath("$.items[0].title").value("페이지 테스트 0"))
                .andExpect(jsonPath("$.items[1].title").value("페이지 테스트 1"))
                .andExpect(jsonPath("$.totalCount").value(5));

        mockMvc.perform(get("/members/{memberId}/loans", memberId)
                        .param("page", "2").param("size", "2"))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.page").value(2))
                .andExpect(jsonPath("$.items.length()").value(1))
                .andExpect(jsonPath("$.items[0].title").value("페이지 테스트 4"))
                .andExpect(jsonPath("$.totalCount").value(5));

        mockMvc.perform(get("/members/{memberId}/loans", memberId)
                        .param("page", "3").param("size", "2"))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.items.length()").value(0))
                .andExpect(jsonPath("$.totalCount").value(5));
    }

    @Test
    void member_without_loans_gets_empty_list_with_zero_total() throws Exception {
        String memberId = registerMember("배정우");

        mockMvc.perform(get("/members/{memberId}/loans", memberId))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.items.length()").value(0))
                .andExpect(jsonPath("$.totalCount").value(0));
    }

    @Test
    void loans_of_other_members_are_not_listed() throws Exception {
        String memberId = registerMember("신예린");
        String otherMemberId = registerMember("오준석");
        loanBookOn(registerBook("다른 회원 책"), otherMemberId, "2026-04-01");

        mockMvc.perform(get("/members/{memberId}/loans", memberId))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.totalCount").value(0));
    }

    @Test
    void unknown_member_returns_404() throws Exception {
        mockMvc.perform(get("/members/{memberId}/loans", UUID.randomUUID()))
                .andExpect(status().isNotFound());
    }

    @Test
    void negative_page_returns_400() throws Exception {
        String memberId = registerMember("류가은");

        mockMvc.perform(get("/members/{memberId}/loans", memberId).param("page", "-1"))
                .andExpect(status().isBadRequest());
    }

    @Test
    void size_out_of_range_returns_400() throws Exception {
        String memberId = registerMember("전민우");

        mockMvc.perform(get("/members/{memberId}/loans", memberId).param("size", "0"))
                .andExpect(status().isBadRequest());
        mockMvc.perform(get("/members/{memberId}/loans", memberId).param("size", "101"))
                .andExpect(status().isBadRequest());
    }

    private String loanBookOn(String bookId, String memberId, String loanedAt) throws Exception {
        String response = mockMvc.perform(post("/loans").contentType(MediaType.APPLICATION_JSON)
                        .content(objectMapper.writeValueAsString(
                                Map.of("bookId", bookId, "memberId", memberId, "loanedAt", loanedAt))))
                .andExpect(status().isCreated())
                .andReturn().getResponse().getContentAsString();
        return objectMapper.readTree(response).get("loanId").asText();
    }

    private String registerBook(String title) throws Exception {
        String response = mockMvc.perform(post("/books")
                        .contentType(MediaType.APPLICATION_JSON)
                        .content("{\"title\":\"" + title + "\"}"))
                .andExpect(status().isCreated())
                .andReturn().getResponse().getContentAsString();
        JsonNode book = objectMapper.readTree(response);
        return book.get("id").asText();
    }

    private String registerMember(String name) throws Exception {
        String response = mockMvc.perform(post("/members")
                        .contentType(MediaType.APPLICATION_JSON)
                        .content("{\"name\":\"" + name + "\"}"))
                .andExpect(status().isCreated())
                .andReturn().getResponse().getContentAsString();
        return objectMapper.readTree(response).get("memberId").asText();
    }
}
